package ae.cfg;

import java.util.List;
import java.util.Objects;

/** A labelled straight-line sequence ending in exactly one terminator (checked by {@link Function}). */
public record Block(String label, List<Instr> instrs) {
    public Block {
        Objects.requireNonNull(label, "label");
        instrs = List.copyOf(instrs);
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/** Dominator tree (Cooper-Harvey-Kennedy iteration over reverse post-order) and dominance frontiers. */
public final class Dominators {
    private final Cfg cfg;
    private final int[] idom;
    private final List<Set<Integer>> frontier = new ArrayList<>();
    private final List<List<Integer>> children = new ArrayList<>();

    public Dominators(Cfg cfg) {
        this.cfg = cfg;
        int n = cfg.size();
        idom = new int[n];
        java.util.Arrays.fill(idom, -1);
        List<Integer> order = cfg.rpo();
        int[] number = new int[n];
        java.util.Arrays.fill(number, -1);
        for (int i = 0; i < order.size(); i++) {
            number[order.get(i)] = i;
        }
        idom[0] = 0;                                   // temporarily its own idom; reset below
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int b : order) {
                if (b == 0) {
                    continue;
                }
                int newIdom = -1;
                for (int p : cfg.pred(b)) {
                    if (idom[p] == -1) {
                        continue;                      // unreachable or not processed yet
                    }
                    newIdom = newIdom == -1 ? p : intersect(p, newIdom, number);
                }
                if (idom[b] != newIdom) {
                    idom[b] = newIdom;
                    changed = true;
                }
            }
        }
        idom[0] = -1;
        for (int b = 0; b < n; b++) {
            frontier.add(new TreeSet<>());
            children.add(new ArrayList<>());
        }
        for (int b = 0; b < n; b++) {
            if (idom[b] >= 0) {
                children.get(idom[b]).add(b);
            }
        }
        for (int b = 0; b < n; b++) {
            if (!cfg.reachable(b)) {
                continue;
            }
            List<Integer> preds = new ArrayList<>();
            for (int p : cfg.pred(b)) {
                if (cfg.reachable(p)) {
                    preds.add(p);
                }
            }
            if (preds.size() + (b == 0 ? 1 : 0) < 2) {
                continue;
            }
            for (int p : preds) {
                int runner = p;
                while (runner != idom[b]) {
                    frontier.get(runner).add(b);
                    runner = idom[runner];
                }
            }
        }
    }

    private int intersect(int a, int b, int[] number) {
        while (a != b) {
            while (number[a] > number[b]) {
                a = a == 0 ? 0 : idom[a];
            }
            while (number[b] > number[a]) {
                b = b == 0 ? 0 : idom[b];
            }
        }
        return a;
    }

    /** Immediate dominator, or -1 for the entry and for unreachable blocks. */
    public int idom(int b) {
        return idom[b];
    }

    /** Reflexive dominance; false if either block is unreachable. */
    public boolean dominates(int a, int b) {
        if (!cfg.reachable(a) || !cfg.reachable(b)) {
            return false;
        }
        for (int x = b; x != -1; x = idom[x]) {
            if (x == a) {
                return true;
            }
        }
        return false;
    }

    public Set<Integer> frontier(int b) {
        return new TreeSet<>(frontier.get(b));
    }

    /** Children in the dominator tree, ascending. */
    public List<Integer> children(int b) {
        return List.copyOf(children.get(b));
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/** Interference graphs and Briggs-style optimistic graph colouring. */
public final class RegAlloc {
    private RegAlloc() { }

    /** Registers of the coloured variables and the set of variables that found none. */
    public record Allocation(Map<String, Integer> regs, Set<String> spilled) {
        public Allocation {
            regs = Map.copyOf(regs);
            spilled = Set.copyOf(spilled);
        }
    }

    /** Interference graph over every variable of {@code f}, as symmetric sorted adjacency sets. */
    public static Map<String, Set<String>> interference(Function f) {
        Cfg cfg = new Cfg(f);
        Liveness live = new Liveness(cfg);
        Map<String, Set<String>> g = new TreeMap<>();
        for (String p : f.params()) {
            g.computeIfAbsent(p, k -> new TreeSet<>());
        }
        for (Block b : f.blocks()) {
            for (Instr i : b.instrs()) {
                i.def().ifPresent(d -> g.computeIfAbsent(d, k -> new TreeSet<>()));
                for (String u : i.uses()) {
                    g.computeIfAbsent(u, k -> new TreeSet<>());
                }
            }
        }
        for (int bi = 0; bi < f.blocks().size(); bi++) {
            List<Instr> ins = f.blocks().get(bi).instrs();
            for (int k = 0; k < ins.size(); k++) {
                Instr i = ins.get(k);
                if (i.def().isEmpty()) {
                    continue;
                }
                String d = i.def().get();
                for (String v : live.liveAfter(bi).get(k)) {
                    boolean copySource = i instanceof Instr.Copy c && c.src().equals(v);
                    if (!v.equals(d) && !copySource) {
                        edge(g, d, v);
                    }
                }
            }
        }
        List<String> params = f.params();
        for (int a = 0; a < params.size(); a++) {
            for (int b = a + 1; b < params.size(); b++) {
                edge(g, params.get(a), params.get(b));
            }
            for (String v : live.liveIn(0)) {
                if (!v.equals(params.get(a))) {
                    edge(g, params.get(a), v);
                }
            }
        }
        return g;
    }

    private static void edge(Map<String, Set<String>> g, String a, String b) {
        g.get(a).add(b);
        g.get(b).add(a);
    }

    public static Allocation allocate(Function f, int k) {
        return color(interference(f), k);
    }

    /** Optimistic colouring with {@code k} registers; see TASK.md for the exact selection rules. */
    public static Allocation color(Map<String, Set<String>> graph, int k) {
        if (k < 1) {
            throw new IllegalArgumentException("k must be >= 1");
        }
        Map<String, Integer> degree = new TreeMap<>();
        graph.forEach((v, ns) -> degree.put(v, ns.size()));
        List<String> stack = new ArrayList<>();
        Set<String> remaining = new TreeSet<>(graph.keySet());
        while (!remaining.isEmpty()) {
            String pick = remaining.stream().filter(v -> degree.get(v) < k)
                    .min(Comparator.<String>comparingInt(degree::get).thenComparing(Comparator.naturalOrder()))
                    .orElseGet(() -> remaining.stream()
                            .max(Comparator.<String>comparingInt(degree::get).thenComparing(Comparator.reverseOrder()))
                            .orElseThrow());
            remaining.remove(pick);
            stack.add(pick);
            for (String n : graph.get(pick)) {
                if (remaining.contains(n)) {
                    degree.merge(n, -1, Integer::sum);
                }
            }
        }
        Map<String, Integer> regs = new TreeMap<>();
        Set<String> spilled = new TreeSet<>();
        for (int s = stack.size() - 1; s >= 0; s--) {
            String v = stack.get(s);
            boolean[] used = new boolean[k];
            for (String n : graph.get(v)) {
                Integer r = regs.get(n);
                if (r != null) {
                    used[r] = true;
                }
            }
            int reg = 0;
            while (reg < k && used[reg]) {
                reg++;
            }
            if (reg == k) {
                spilled.add(v);
            } else {
                regs.put(v, reg);
            }
        }
        return new Allocation(regs, spilled);
    }

    /** Rewrites every variable to {@code r<reg>}; the allocation must have no spills. */
    public static Function rename(Function f, Allocation a) {
        if (!a.spilled().isEmpty()) {
            throw new IllegalArgumentException("cannot rename with spilled variables " + a.spilled());
        }
        java.util.function.UnaryOperator<String> r = v -> {
            Integer reg = a.regs().get(v);
            if (reg == null) {
                throw new IllegalArgumentException("no register for " + v);
            }
            return "r" + reg;
        };
        List<String> params = f.params().stream().map(r).toList();
        List<Block> blocks = new ArrayList<>();
        for (Block b : f.blocks()) {
            List<Instr> ins = new ArrayList<>();
            for (Instr i : b.instrs()) {
                ins.add(switch (i) {
                    case Instr.Const c -> new Instr.Const(r.apply(c.dst()), c.value());
                    case Instr.Bin x -> new Instr.Bin(r.apply(x.dst()), x.op(), r.apply(x.a()), r.apply(x.b()));
                    case Instr.Copy c -> new Instr.Copy(r.apply(c.dst()), r.apply(c.src()));
                    case Instr.Br x -> new Instr.Br(r.apply(x.cond()), x.thenLabel(), x.elseLabel());
                    case Instr.Jmp j -> j;
                    case Instr.Ret x -> new Instr.Ret(r.apply(x.value()));
                });
            }
            blocks.add(new Block(b.label(), ins));
        }
        return new Function(f.name(), params, blocks);
    }
}

package ae.cfg;

import java.util.List;
import java.util.Optional;

/** One three-address instruction. Branches, jumps and returns are terminators. */
public sealed interface Instr {
    /** Binary operators; {@code LT} and {@code EQ} yield 1 or 0. */
    enum Op { ADD, SUB, MUL, LT, EQ }

    record Const(String dst, long value) implements Instr { }

    record Bin(String dst, Op op, String a, String b) implements Instr { }

    record Copy(String dst, String src) implements Instr { }

    /** {@code cond != 0} goes to {@code thenLabel}, otherwise to {@code elseLabel}. */
    record Br(String cond, String thenLabel, String elseLabel) implements Instr { }

    record Jmp(String target) implements Instr { }

    record Ret(String value) implements Instr { }

    /** The variable this instruction assigns, if any. */
    default Optional<String> def() {
        return switch (this) {
            case Const c -> Optional.of(c.dst());
            case Bin b -> Optional.of(b.dst());
            case Copy c -> Optional.of(c.dst());
            case Br b -> Optional.empty();
            case Jmp j -> Optional.empty();
            case Ret r -> Optional.empty();
        };
    }

    /** Operand variables, in source order. */
    default List<String> uses() {
        return switch (this) {
            case Const c -> List.of();
            case Bin b -> List.of(b.a(), b.b());
            case Copy c -> List.of(c.src());
            case Br b -> List.of(b.cond());
            case Jmp j -> List.of();
            case Ret r -> List.of(r.value());
        };
    }

    default boolean isTerminator() {
        return this instanceof Br || this instanceof Jmp || this instanceof Ret;
    }

    /** Labels this instruction may transfer control to. */
    default List<String> targets() {
        return switch (this) {
            case Br b -> List.of(b.thenLabel(), b.elseLabel());
            case Jmp j -> List.of(j.target());
            default -> List.of();
        };
    }

    /** Text form, as accepted by {@link Function#parse}. */
    default String text() {
        return switch (this) {
            case Const c -> c.dst() + " = const " + c.value();
            case Bin b -> b.dst() + " = " + b.op().name().toLowerCase(java.util.Locale.ROOT) + " " + b.a() + ", " + b.b();
            case Copy c -> c.dst() + " = copy " + c.src();
            case Br b -> "br " + b.cond() + ", " + b.thenLabel() + ", " + b.elseLabel();
            case Jmp j -> "jmp " + j.target();
            case Ret r -> "ret " + r.value();
        };
    }
}

package ae.cfg;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/** Natural loops, loop depth and reducibility. */
public final class Loops {
    /** One loop per header: its body (header included, sorted) and the tails of its back edges (ascending). */
    public record Loop(int header, Set<Integer> blocks, List<Integer> tails) {
        public Loop {
            blocks = Set.copyOf(blocks);
            tails = List.copyOf(tails);
        }
    }

    private final List<Loop> loops = new ArrayList<>();
    private final int[] depth;
    private final boolean reducible;

    public Loops(Cfg cfg, Dominators dom) {
        int n = cfg.size();
        TreeMap<Integer, List<Integer>> tailsByHeader = new TreeMap<>();
        for (int t = 0; t < n; t++) {
            for (int h : cfg.succ(t)) {
                if (dom.dominates(h, t)) {
                    tailsByHeader.computeIfAbsent(h, k -> new ArrayList<>()).add(t);
                }
            }
        }
        depth = new int[n];
        for (var e : tailsByHeader.entrySet()) {
            int header = e.getKey();
            Set<Integer> body = new TreeSet<>();
            body.add(header);
            ArrayDeque<Integer> work = new ArrayDeque<>();
            for (int t : e.getValue()) {
                if (body.add(t)) {
                    work.push(t);
                }
            }
            while (!work.isEmpty()) {
                for (int p : cfg.pred(work.pop())) {
                    if (cfg.reachable(p) && body.add(p)) {
                        work.push(p);
                    }
                }
            }
            for (int b : body) {
                depth[b]++;
            }
            loops.add(new Loop(header, body, e.getValue()));
        }
        reducible = acyclicWithoutBackEdges(cfg, dom);
    }

    /** Colour DFS over reachable blocks, skipping back edges; a cycle left over means an irreducible region. */
    private static boolean acyclicWithoutBackEdges(Cfg cfg, Dominators dom) {
        int n = cfg.size();
        int[] state = new int[n];                 // 0 new, 1 on stack, 2 done
        int[] next = new int[n];
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        state[0] = 1;
        while (!stack.isEmpty()) {
            int b = stack.peek();
            List<Integer> succ = cfg.succ(b);
            if (next[b] < succ.size()) {
                int s = succ.get(next[b]++);
                if (dom.dominates(s, b)) {
                    continue;                      // back edge
                }
                if (state[s] == 1) {
                    return false;
                }
                if (state[s] == 0) {
                    state[s] = 1;
                    stack.push(s);
                }
            } else {
                state[b] = 2;
                stack.pop();
            }
        }
        return true;
    }

    /** Loops ordered by header index. */
    public List<Loop> loops() {
        return List.copyOf(loops);
    }

    /** Number of loops containing block b. */
    public int depth(int b) {
        return depth[b];
    }

    public boolean reducible() {
        return reducible;
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A function: parameters plus blocks; block 0 is the entry. Validated on construction. */
public record Function(String name, List<String> params, List<Block> blocks) {
    private static final String ID = "[A-Za-z_][A-Za-z0-9_]*";
    private static final Pattern HEADER = Pattern.compile("func (" + ID + ")\\((.*)\\)");
    private static final Pattern LABEL = Pattern.compile("(" + ID + "):");
    private static final Pattern CONST = Pattern.compile("(" + ID + ") = const (-?[0-9]+)");
    private static final Pattern BIN = Pattern.compile("(" + ID + ") = (add|sub|mul|lt|eq) (" + ID + "), (" + ID + ")");
    private static final Pattern COPY = Pattern.compile("(" + ID + ") = copy (" + ID + ")");
    private static final Pattern BR = Pattern.compile("br (" + ID + "), (" + ID + "), (" + ID + ")");
    private static final Pattern JMP = Pattern.compile("jmp (" + ID + ")");
    private static final Pattern RET = Pattern.compile("ret (" + ID + ")");

    public Function {
        Objects.requireNonNull(name, "name");
        params = List.copyOf(params);
        blocks = List.copyOf(blocks);
        validate(params, blocks);
    }

    private static void validate(List<String> params, List<Block> blocks) {
        if (blocks.isEmpty()) {
            throw new IllegalArgumentException("function has no blocks");
        }
        Set<String> paramSet = new HashSet<>();
        for (String p : params) {
            if (!paramSet.add(p)) {
                throw new IllegalArgumentException("duplicate param " + p);
            }
        }
        Set<String> labels = new HashSet<>();
        Set<String> defined = new HashSet<>(paramSet);
        for (Block b : blocks) {
            if (!labels.add(b.label())) {
                throw new IllegalArgumentException("duplicate label " + b.label());
            }
            List<Instr> ins = b.instrs();
            if (ins.isEmpty() || !ins.get(ins.size() - 1).isTerminator()) {
                throw new IllegalArgumentException("block " + b.label() + " must end with a terminator");
            }
            for (int i = 0; i < ins.size() - 1; i++) {
                if (ins.get(i).isTerminator()) {
                    throw new IllegalArgumentException("block " + b.label() + " has a terminator before its last instruction");
                }
            }
            ins.forEach(i -> i.def().ifPresent(defined::add));
        }
        for (Block b : blocks) {
            for (Instr i : b.instrs()) {
                for (String t : i.targets()) {
                    if (!labels.contains(t)) {
                        throw new IllegalArgumentException("unknown label " + t + " in block " + b.label());
                    }
                }
                for (String u : i.uses()) {
                    if (!defined.contains(u)) {
                        throw new IllegalArgumentException("undefined variable " + u + " in block " + b.label());
                    }
                }
            }
        }
    }

    /** Parses the text form described in TASK.md. */
    public static Function parse(String text) {
        Objects.requireNonNull(text, "text");
        String name = null;
        List<String> params = new ArrayList<>();
        List<Block> blocks = new ArrayList<>();
        String label = null;
        List<Instr> cur = new ArrayList<>();
        int lineNo = 0;
        for (String raw : text.split("\n", -1)) {
            lineNo++;
            int hash = raw.indexOf('#');
            String line = (hash >= 0 ? raw.substring(0, hash) : raw).strip();
            if (line.isEmpty()) {
                continue;
            }
            if (name == null) {
                Matcher m = HEADER.matcher(line);
                if (!m.matches()) {
                    throw syntax(lineNo, "expected function header");
                }
                name = m.group(1);
                String ps = m.group(2).strip();
                if (!ps.isEmpty()) {
                    for (String p : ps.split(",", -1)) {
                        if (!p.strip().matches(ID)) {
                            throw syntax(lineNo, "bad parameter '" + p.strip() + "'");
                        }
                        params.add(p.strip());
                    }
                }
                continue;
            }
            Matcher lm = LABEL.matcher(line);
            if (lm.matches()) {
                if (label != null) {
                    blocks.add(new Block(label, cur));
                }
                label = lm.group(1);
                cur = new ArrayList<>();
                continue;
            }
            if (label == null) {
                throw syntax(lineNo, "instruction before the first label");
            }
            cur.add(instr(line, lineNo));
        }
        if (name == null) {
            throw new IllegalArgumentException("line 1: expected function header");
        }
        if (label != null) {
            blocks.add(new Block(label, cur));
        }
        return new Function(name, params, blocks);
    }

    private static Instr instr(String line, int lineNo) {
        Matcher m;
        if ((m = CONST.matcher(line)).matches()) {
            try {
                return new Instr.Const(m.group(1), Long.parseLong(m.group(2)));
            } catch (NumberFormatException e) {
                throw syntax(lineNo, "constant out of range");
            }
        }
        if ((m = BIN.matcher(line)).matches()) {
            return new Instr.Bin(m.group(1), Instr.Op.valueOf(m.group(2).toUpperCase(java.util.Locale.ROOT)), m.group(3), m.group(4));
        }
        if ((m = COPY.matcher(line)).matches()) {
            return new Instr.Copy(m.group(1), m.group(2));
        }
        if ((m = BR.matcher(line)).matches()) {
            return new Instr.Br(m.group(1), m.group(2), m.group(3));
        }
        if ((m = JMP.matcher(line)).matches()) {
            return new Instr.Jmp(m.group(1));
        }
        if ((m = RET.matcher(line)).matches()) {
            return new Instr.Ret(m.group(1));
        }
        throw syntax(lineNo, "cannot parse '" + line + "'");
    }

    private static IllegalArgumentException syntax(int lineNo, String msg) {
        return new IllegalArgumentException("line " + lineNo + ": " + msg);
    }

    /** Canonical text; {@code parse(toText())} equals this function. */
    public String toText() {
        StringBuilder sb = new StringBuilder("func ").append(name).append('(').append(String.join(", ", params)).append(")\n");
        for (Block b : blocks) {
            sb.append(b.label()).append(":\n");
            for (Instr i : b.instrs()) {
                sb.append("  ").append(i.text()).append('\n');
            }
        }
        return sb.toString();
    }

    /** Label -> block index. */
    Map<String, Integer> labelIndex() {
        Map<String, Integer> m = new HashMap<>();
        for (int i = 0; i < blocks.size(); i++) {
            m.put(blocks.get(i).label(), i);
        }
        return m;
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/** Dead-code elimination driven by liveness. */
public final class Dce {
    private Dce() { }

    /** Removes unreachable blocks, then dead definitions until a fixed point. */
    public static Function run(Function f) {
        Function cur = dropUnreachable(f);
        while (true) {
            Function next = removeDeadDefs(cur);
            if (next.equals(cur)) {
                return cur;
            }
            cur = next;
        }
    }

    private static Function dropUnreachable(Function f) {
        Cfg cfg = new Cfg(f);
        List<Block> kept = new ArrayList<>();
        for (int b = 0; b < cfg.size(); b++) {
            if (cfg.reachable(b)) {
                kept.add(f.blocks().get(b));
            }
        }
        return new Function(f.name(), f.params(), kept);
    }

    private static Function removeDeadDefs(Function f) {
        Liveness live = new Liveness(new Cfg(f));
        List<Block> blocks = new ArrayList<>();
        for (int b = 0; b < f.blocks().size(); b++) {
            Block blk = f.blocks().get(b);
            List<Set<String>> after = live.liveAfter(b);
            List<Instr> kept = new ArrayList<>();
            for (int i = 0; i < blk.instrs().size(); i++) {
                Instr ins = blk.instrs().get(i);
                boolean dead = ins.def().isPresent() && !after.get(i).contains(ins.def().get());
                if (!dead) {
                    kept.add(ins);
                }
            }
            blocks.add(new Block(blk.label(), kept));
        }
        return new Function(f.name(), f.params(), blocks);
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/** Backward live-variable analysis, block level and instruction level. */
public final class Liveness {
    private final List<Set<String>> in = new ArrayList<>();
    private final List<Set<String>> out = new ArrayList<>();
    private final List<List<Set<String>>> after = new ArrayList<>();

    public Liveness(Cfg cfg) {
        Function f = cfg.function();
        int n = cfg.size();
        List<Set<String>> use = new ArrayList<>();   // upward-exposed uses
        List<Set<String>> def = new ArrayList<>();
        for (int b = 0; b < n; b++) {
            Set<String> u = new TreeSet<>();
            Set<String> d = new TreeSet<>();
            for (Instr i : f.blocks().get(b).instrs()) {
                for (String v : i.uses()) {
                    if (!d.contains(v)) {
                        u.add(v);
                    }
                }
                i.def().ifPresent(d::add);
            }
            use.add(u);
            def.add(d);
            in.add(new TreeSet<>());
            out.add(new TreeSet<>());
        }
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int b = n - 1; b >= 0; b--) {
                Set<String> o = new TreeSet<>();
                for (int s : cfg.succ(b)) {
                    o.addAll(in.get(s));
                }
                Set<String> i = new TreeSet<>(o);
                i.removeAll(def.get(b));
                i.addAll(use.get(b));
                if (!o.equals(out.get(b)) || !i.equals(in.get(b))) {
                    out.set(b, o);
                    in.set(b, i);
                    changed = true;
                }
            }
        }
        for (int b = 0; b < n; b++) {
            List<Instr> ins = f.blocks().get(b).instrs();
            Set<String>[] sets = newArray(ins.size());
            Set<String> live = new TreeSet<>(out.get(b));
            for (int k = ins.size() - 1; k >= 0; k--) {
                sets[k] = new TreeSet<>(live);
                ins.get(k).def().ifPresent(live::remove);
                live.addAll(ins.get(k).uses());
            }
            after.add(List.of(sets));
        }
    }

    @SuppressWarnings("unchecked")
    private static Set<String>[] newArray(int n) {
        return (Set<String>[]) new Set<?>[n];
    }

    public Set<String> liveIn(int b) {
        return Set.copyOf(in.get(b)).isEmpty() ? Set.of() : new TreeSet<>(in.get(b));
    }

    public Set<String> liveOut(int b) {
        return new TreeSet<>(out.get(b));
    }

    /** For each instruction of block b, the variables live immediately after it. */
    public List<Set<String>> liveAfter(int b) {
        return after.get(b);
    }
}

package ae.cfg;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

/** Reference interpreter: wrapping {@code long} arithmetic and a step budget. */
public final class Interp {
    private Interp() { }

    /**
     * Runs {@code f}; empty if more than {@code maxSteps} instructions would be executed.
     *
     * @throws IllegalStateException if an unassigned variable is read
     * @throws IllegalArgumentException if {@code args} does not match the parameter list
     */
    public static Optional<Long> run(Function f, long[] args, int maxSteps) {
        if (args.length != f.params().size()) {
            throw new IllegalArgumentException("expected " + f.params().size() + " arguments, got " + args.length);
        }
        Map<String, Long> env = new HashMap<>();
        for (int i = 0; i < args.length; i++) {
            env.put(f.params().get(i), args[i]);
        }
        Map<String, Integer> labels = f.labelIndex();
        int block = 0;
        int steps = 0;
        while (true) {
            for (Instr i : f.blocks().get(block).instrs()) {
                if (++steps > maxSteps) {
                    return Optional.empty();
                }
                switch (i) {
                    case Instr.Const c -> env.put(c.dst(), c.value());
                    case Instr.Copy c -> env.put(c.dst(), read(env, c.src()));
                    case Instr.Bin b -> env.put(b.dst(), apply(b.op(), read(env, b.a()), read(env, b.b())));
                    case Instr.Br b -> block = labels.get(read(env, b.cond()) != 0 ? b.thenLabel() : b.elseLabel());
                    case Instr.Jmp j -> block = labels.get(j.target());
                    case Instr.Ret r -> {
                        return Optional.of(read(env, r.value()));
                    }
                }
            }
        }
    }

    private static long read(Map<String, Long> env, String v) {
        Long x = env.get(v);
        if (x == null) {
            throw new IllegalStateException("read of unassigned variable " + v);
        }
        return x;
    }

    private static long apply(Instr.Op op, long a, long b) {
        return switch (op) {
            case ADD -> a + b;
            case SUB -> a - b;
            case MUL -> a * b;
            case LT -> a < b ? 1 : 0;
            case EQ -> a == b ? 1 : 0;
        };
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Control-flow graph over the blocks of a function (block index = position in the function). */
public final class Cfg {
    private final Function fn;
    private final Map<String, Integer> index;
    private final List<List<Integer>> succ = new ArrayList<>();
    private final List<List<Integer>> pred = new ArrayList<>();
    private final List<Integer> rpo;
    private final boolean[] reachable;

    public Cfg(Function fn) {
        this.fn = fn;
        this.index = fn.labelIndex();
        int n = fn.blocks().size();
        for (int i = 0; i < n; i++) {
            succ.add(new ArrayList<>());
            pred.add(new ArrayList<>());
        }
        for (int b = 0; b < n; b++) {
            List<Instr> ins = fn.blocks().get(b).instrs();
            for (String t : ins.get(ins.size() - 1).targets()) {
                int s = index.get(t);
                if (!succ.get(b).contains(s)) {
                    succ.get(b).add(s);
                    pred.get(s).add(b);
                }
            }
        }
        this.reachable = new boolean[n];
        this.rpo = reversePostOrder(n);
        for (int b : rpo) {
            reachable[b] = true;
        }
    }

    /** Iterative DFS post-order from the entry, reversed. */
    private List<Integer> reversePostOrder(int n) {
        boolean[] seen = new boolean[n];
        int[] next = new int[n];
        List<Integer> post = new ArrayList<>();
        int[] stack = new int[n];
        int sp = 0;
        stack[sp++] = 0;
        seen[0] = true;
        while (sp > 0) {
            int b = stack[sp - 1];
            if (next[b] < succ.get(b).size()) {
                int s = succ.get(b).get(next[b]++);
                if (!seen[s]) {
                    seen[s] = true;
                    stack[sp++] = s;
                }
            } else {
                post.add(b);
                sp--;
            }
        }
        List<Integer> out = new ArrayList<>(post.reversed());
        return List.copyOf(out);
    }

    public Function function() {
        return fn;
    }

    public int size() {
        return fn.blocks().size();
    }

    public List<Integer> succ(int b) {
        return List.copyOf(succ.get(b));
    }

    public List<Integer> pred(int b) {
        return List.copyOf(pred.get(b));
    }

    public boolean reachable(int b) {
        return reachable[b];
    }

    /** Reachable blocks in reverse post-order; the entry comes first. */
    public List<Integer> rpo() {
        return rpo;
    }

    public int index(String label) {
        Integer i = index.get(label);
        if (i == null) {
            throw new IllegalArgumentException("unknown label " + label);
        }
        return i;
    }
}

