package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import ae.cfg.Instr.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class ParseTest {
    @Test
    void parsesEveryInstructionKind() {
        Function f = Function.parse("""
                # a comment
                func k(a, b)

                start:   # entry
                  x = const -7
                  y = add a, b
                  z = sub x, y
                  w = mul z, z
                  l = lt w, a
                  e = eq l, l
                  c = copy e
                  br c, start, end
                end:
                  ret c
                """);
        assertEquals("k", f.name());
        assertEquals(List.of("a", "b"), f.params());
        assertEquals(2, f.blocks().size());
        assertEquals(List.of(
                new Const("x", -7), new Bin("y", Instr.Op.ADD, "a", "b"), new Bin("z", Instr.Op.SUB, "x", "y"),
                new Bin("w", Instr.Op.MUL, "z", "z"), new Bin("l", Instr.Op.LT, "w", "a"),
                new Bin("e", Instr.Op.EQ, "l", "l"), new Copy("c", "e"), new Br("c", "start", "end")),
                f.blocks().get(0).instrs());
        assertEquals(List.of(new Ret("c")), f.blocks().get(1).instrs());
    }

    @Test
    void defUsesAndTargets() {
        Instr bin = new Bin("d", Instr.Op.ADD, "p", "q");
        assertEquals(Optional.of("d"), bin.def());
        assertEquals(List.of("p", "q"), bin.uses());
        assertFalse(bin.isTerminator());
        assertEquals(Optional.of("d"), new Const("d", 1).def());
        assertEquals(List.of(), new Const("d", 1).uses());
        assertEquals(List.of("s"), new Copy("d", "s").uses());
        Instr br = new Br("c", "t", "e");
        assertTrue(br.isTerminator());
        assertEquals(Optional.empty(), br.def());
        assertEquals(List.of("c"), br.uses());
        assertEquals(List.of("t", "e"), br.targets());
        assertEquals(List.of("L"), new Jmp("L").targets());
        assertEquals(List.of("v"), new Ret("v").uses());
        assertEquals(List.of(), new Ret("v").targets());
        assertEquals(List.of(), bin.targets());
    }

    @Test
    void textRoundTrips() {
        for (String src : List.of(Fixtures.DIAMOND, Fixtures.LOOP, Fixtures.IRREDUCIBLE, Fixtures.UNREACHABLE,
                Fixtures.SELF_LOOP, Fixtures.SUM)) {
            Function f = Function.parse(src);
            assertEquals(f, Function.parse(f.toText()), src);
        }
        assertEquals("""
                func g(n)
                entry:
                  i = const 0
                  one = const 1
                  jmp head
                head:
                  c = lt i, n
                  br c, body, exit
                body:
                  i = add i, one
                  jmp head
                exit:
                  ret i
                """, Function.parse(Fixtures.LOOP).toText());
    }

    private static void rejects(String src, String messagePart) {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> Function.parse(src), src);
        assertTrue(e.getMessage().contains(messagePart), "message was: " + e.getMessage());
    }

    /** Each rejection has a control (the line below it in the same test) differing only by the defect. */
    @Test
    void rejectsMalformedPrograms() {
        String ok = "func f(a)\nb:\n  ret a\n";
        assertDoesNotThrow(() -> Function.parse(ok));
        rejects("func f(a)\nb:\n  x = const 1\n", "terminator");                 // missing terminator
        rejects("func f(a)\nb:\n  ret a\n  x = const 1\n  ret a\n", "terminator"); // instruction after terminator
        rejects("func f(a)\nb:\n  ret a\nb:\n  ret a\n", "duplicate label");
        rejects("func f(a)\nb:\n  jmp nowhere\n", "unknown label");
        rejects("func f(a, a)\nb:\n  ret a\n", "duplicate param");
        rejects("func f(a)\nb:\n  ret zz\n", "undefined variable zz");
        rejects("func f(a)\nb:\n  x = div a, a\n  ret x\n", "line 3");
        rejects("func f(a)\n  ret a\n", "line 2");                                  // instruction before first label
        rejects("func f(a)\n", "no blocks");
        rejects("func f(a)\nb:\nc:\n  ret a\n", "terminator");                     // empty block
        rejects("", "header");
        rejects("func f(a\nb:\n  ret a\n", "line 1");
        rejects("func f(a)\nb:\n  x = const 1.5\n  ret x\n", "line 3");
        rejects("func f(a)\nb:\n  x = add a\n  ret x\n", "line 3");
        rejects("func f(a)\nb:\n  br a, b\n", "line 3");
        rejects("func f(a)\nb:\n  1x = const 1\n  ret a\n", "line 3");
    }

    @Test
    void usedVariableMayBeDefinedLaterInTextOrOnOnePathOnly() {
        assertDoesNotThrow(() -> Function.parse("func f(a)\nb:\n  br a, c, d\nc:\n  x = const 1\n  jmp d\nd:\n  ret x\n"));
        assertDoesNotThrow(() -> Function.parse("func f(a)\nb:\n  jmp c\nc:\n  y = add x, a\n  jmp d\nd:\n  x = const 1\n  ret y\n"));
    }

    @Test
    void recordsCopyTheirLists() {
        List<Instr> instrs = new ArrayList<>(List.of(new Ret("a")));
        Block b = new Block("b", instrs);
        instrs.add(new Const("x", 1));
        assertEquals(1, b.instrs().size());
        assertThrows(UnsupportedOperationException.class, () -> b.instrs().add(new Ret("a")));

        List<String> params = new ArrayList<>(List.of("a"));
        List<Block> blocks = new ArrayList<>(List.of(b));
        Function f = new Function("f", params, blocks);
        params.add("zz");
        blocks.clear();
        assertEquals(List.of("a"), f.params());
        assertEquals(1, f.blocks().size());
    }

    @Test
    void nullsAreRejected() {
        assertThrows(NullPointerException.class, () -> Function.parse(null));
        assertThrows(NullPointerException.class, () -> new Block(null, List.of(new Ret("a"))));
    }
}

package ae.cfg;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/** Seeded random program generators. */
final class Gen {
    private Gen() { }

    private static final String[] OPS = {"add", "sub", "mul", "lt", "eq"};

    /**
     * Structured programs: straight-line code, if/else and counter-bounded while loops (so every program terminates
     * well inside the step budget). Variables v0..v(m-1) are all assigned in the entry block, so no read is ever
     * undefined. Loop counters/bounds are fresh variables defined right before their loop.
     */
    static String structured(Random rnd, int params, int vars) {
        return new Structured(rnd, params, vars).build();
    }

    private static final class Structured {
        final Random rnd;
        final int params;
        final int vars;
        final StringBuilder sb = new StringBuilder();
        int labels;
        int loops;

        Structured(Random rnd, int params, int vars) {
            this.rnd = rnd;
            this.params = params;
            this.vars = vars;
        }

        String v() {
            return "v" + rnd.nextInt(vars);
        }

        String operand() {
            return rnd.nextInt(5) == 0 ? "p" + rnd.nextInt(Math.max(1, params)) : v();
        }

        void line(String s) {
            sb.append("  ").append(s).append('\n');
        }

        void label(String l) {
            sb.append(l).append(":\n");
        }

        void assign() {
            switch (rnd.nextInt(4)) {
                case 0 -> line(v() + " = const " + (rnd.nextInt(21) - 10));
                case 1 -> line(v() + " = copy " + operand());
                default -> line(v() + " = " + OPS[rnd.nextInt(OPS.length)] + " " + operand() + ", " + operand());
            }
        }

        void stmts(int depth, int count) {
            for (int i = 0; i < count; i++) {
                int pick = depth <= 0 ? 0 : rnd.nextInt(6);
                if (pick <= 3) {
                    assign();
                } else if (pick == 4) {
                    ifElse(depth);
                } else {
                    whileLoop(depth);
                }
            }
        }

        void ifElse(int depth) {
            int id = labels++;
            String c = "c" + id;
            line(c + " = " + OPS[3 + rnd.nextInt(2)] + " " + operand() + ", " + operand());
            line("br " + c + ", T" + id + ", E" + id);
            label("T" + id);
            stmts(depth - 1, 1 + rnd.nextInt(3));
            line("jmp J" + id);
            label("E" + id);
            if (rnd.nextBoolean()) {
                stmts(depth - 1, 1 + rnd.nextInt(2));
            }
            line("jmp J" + id);
            label("J" + id);
        }

        void whileLoop(int depth) {
            int id = labels++;
            String i = "i" + id;
            String bound = "n" + id;
            String one = "o" + id;
            line(i + " = const 0");
            line(bound + " = const " + (1 + rnd.nextInt(3)));
            line(one + " = const 1");
            line("jmp H" + id);
            label("H" + id);
            line("k" + id + " = lt " + i + ", " + bound);
            line("br k" + id + ", B" + id + ", X" + id);
            label("B" + id);
            stmts(depth - 1, 1 + rnd.nextInt(3));
            line(i + " = add " + i + ", " + one);
            line("jmp H" + id);
            label("X" + id);
        }

        String build() {
            StringBuilder head = new StringBuilder("func s(");
            for (int i = 0; i < params; i++) {
                head.append(i == 0 ? "" : ", ").append('p').append(i);
            }
            head.append(")\nentry:\n");
            sb.append(head);
            for (int i = 0; i < vars; i++) {
                line("v" + i + (params > 0 && rnd.nextBoolean() ? " = copy p" + rnd.nextInt(params)
                        : " = const " + (rnd.nextInt(7) - 3)));
            }
            stmts(3, 3 + rnd.nextInt(6));
            String acc = "v0";
            for (int i = 1; i < vars; i++) {
                if (rnd.nextBoolean()) {
                    line("t" + i + " = add " + acc + ", v" + i);
                    acc = "t" + i;
                }
            }
            line("ret " + acc);
            return sb.toString();
        }
    }

    /**
     * Arbitrary (possibly irreducible, possibly with unreachable blocks) control-flow graphs of 1..9 blocks. Every
     * block has a few random instructions over {a, x, y, z}; x, y, z are defined by the first instruction of block 0
     * so the text is valid, while reads can still be "undefined" at run time (these programs are only analysed).
     */
    static String randomCfg(Random rnd) {
        int n = 1 + rnd.nextInt(9);
        String[] vars = {"a", "x", "y", "z"};
        StringBuilder sb = new StringBuilder("func r(a)\n");
        for (int b = 0; b < n; b++) {
            sb.append("b").append(b).append(":\n");
            if (b == 0) {
                sb.append("  x = const 1\n  y = const 2\n  z = const 3\n");
            }
            int count = rnd.nextInt(4);
            for (int i = 0; i < count; i++) {
                String d = vars[1 + rnd.nextInt(3)];
                if (rnd.nextInt(3) == 0) {
                    sb.append("  ").append(d).append(" = copy ").append(vars[rnd.nextInt(4)]).append('\n');
                } else {
                    sb.append("  ").append(d).append(" = add ").append(vars[rnd.nextInt(4)]).append(", ")
                            .append(vars[rnd.nextInt(4)]).append('\n');
                }
            }
            switch (rnd.nextInt(4)) {
                case 0 -> sb.append("  ret ").append(vars[rnd.nextInt(4)]).append('\n');
                case 1 -> sb.append("  jmp b").append(rnd.nextInt(n)).append('\n');
                default -> sb.append("  br ").append(vars[rnd.nextInt(4)]).append(", b").append(rnd.nextInt(n))
                        .append(", b").append(rnd.nextInt(n)).append('\n');
            }
        }
        return sb.toString();
    }

    static List<long[]> argSets(Random rnd, int params, int count) {
        List<long[]> out = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            long[] a = new long[params];
            for (int j = 0; j < params; j++) {
                a[j] = rnd.nextInt(15) - 7;
            }
            out.add(a);
        }
        return out;
    }
}

package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Optional;
import org.junit.jupiter.api.Test;

class InterpTest {
    @Test
    void sumLoop() {
        Function f = Function.parse(Fixtures.SUM);
        assertEquals(Optional.of(10L), Interp.run(f, new long[] {4}, 1000));
        assertEquals(Optional.of(0L), Interp.run(f, new long[] {0}, 1000));
        assertEquals(Optional.of(0L), Interp.run(f, new long[] {-3}, 1000));
        assertEquals(Optional.of(5050L), Interp.run(f, new long[] {100}, 10_000));
    }

    @Test
    void stepBudgetIsExact() {
        // n = -1: entry(4 instrs) + head(2: c = lt n,i is true at once) + exit(1) = 7 instructions.
        Function f = Function.parse(Fixtures.SUM);
        assertEquals(Optional.of(0L), Interp.run(f, new long[] {-1}, 7));
        assertEquals(Optional.empty(), Interp.run(f, new long[] {-1}, 6));
        // n = 0 takes one trip through the body: 4 + 2 + 3 (body) + 2 + 1 = 12.
        assertEquals(Optional.of(0L), Interp.run(f, new long[] {0}, 12));
        assertEquals(Optional.empty(), Interp.run(f, new long[] {0}, 11));
        Function inf = Function.parse("func i()\nb:\n  jmp b\n");
        assertEquals(Optional.empty(), Interp.run(inf, new long[0], 1000));
    }

    @Test
    void arithmeticWrapsAndComparesGiveOneOrZero() {
        Function f = Function.parse("""
                func w(a)
                b:
                  m = const 9223372036854775807
                  s = add m, a
                  t = sub s, a
                  u = mul a, a
                  l = lt s, m
                  q = eq t, m
                  r = add l, q
                  v = add r, u
                  ret v
                """);
        // a = 1: s wraps to MIN, so lt(s,m)=1; t = MIN-1 wraps back to MAX so eq=1; u=1; v = 1+1+1.
        assertEquals(Optional.of(3L), Interp.run(f, new long[] {1}, 100));
        // a = 0: s = m, lt = 0, t = m so eq = 1, u = 0 -> 1.
        assertEquals(Optional.of(1L), Interp.run(f, new long[] {0}, 100));
    }

    @Test
    void readingAnUnassignedVariableFails() {
        Function f = Function.parse("func u(a)\nentry:\n  br a, l, r\nl:\n  x = const 1\n  jmp r\nr:\n  ret x\n");
        assertEquals(Optional.of(1L), Interp.run(f, new long[] {1}, 100));
        assertThrows(IllegalStateException.class, () -> Interp.run(f, new long[] {0}, 100));
    }

    @Test
    void wrongArgumentCountFails() {
        Function f = Function.parse(Fixtures.SUM);
        assertThrows(IllegalArgumentException.class, () -> Interp.run(f, new long[0], 10));
        assertThrows(IllegalArgumentException.class, () -> Interp.run(f, new long[] {1, 2}, 10));
    }
}

package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Map;
import java.util.Optional;
import java.util.Random;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import org.junit.jupiter.api.Test;

class RegAllocTest {
    private static final String STRAIGHT = """
            func r(a, b)
            entry:
              x = add a, b
              y = mul x, a
              z = add y, b
              ret z
            """;

    private static Map<String, Set<String>> graph(String... edges) {
        Map<String, Set<String>> g = new TreeMap<>();
        for (String e : edges) {
            String[] p = e.split("-");
            g.computeIfAbsent(p[0], k -> new TreeSet<>()).add(p[1]);
            g.computeIfAbsent(p[1], k -> new TreeSet<>()).add(p[0]);
        }
        return g;
    }

    @Test
    void interferenceOfStraightLineCode() {
        // after x=add: {a,b,x} -> x-a, x-b; after y=mul: {b,y} -> y-b; after z: {z}. Params a-b.
        Map<String, Set<String>> g = RegAlloc.interference(Function.parse(STRAIGHT));
        assertEquals(Map.of(
                "a", Set.of("b", "x"),
                "b", Set.of("a", "x", "y"),
                "x", Set.of("a", "b"),
                "y", Set.of("b"),
                "z", Set.of()), g);
    }

    @Test
    void copyDoesNotInterfereWithItsSource() {
        Function f = Function.parse("func c(a)\nb:\n  x = copy a\n  y = add x, a\n  ret y\n");
        // After the copy both a and x are live (a is read by y) but they hold the same value.
        assertEquals(Map.of("a", Set.of(), "x", Set.of(), "y", Set.of()), RegAlloc.interference(f));
        // Control: an add instead of a copy makes them interfere.
        Function g = Function.parse("func c(a)\nb:\n  x = add a, a\n  y = add x, a\n  ret y\n");
        assertEquals(Set.of("x"), RegAlloc.interference(g).get("a"));
    }

    @Test
    void deadDefinitionStillInterferesWithLiveVariables() {
        Function f = Function.parse("func c(a)\nb:\n  dead = const 9\n  ret a\n");
        assertEquals(Set.of("a"), RegAlloc.interference(f).get("dead"));
    }

    @Test
    void parametersInterfereEvenWhenOneIsDead() {
        Function f = Function.parse("func p(a, b, c)\nb0:\n  ret c\n");
        Map<String, Set<String>> g = RegAlloc.interference(f);
        assertEquals(Set.of("b", "c"), g.get("a"));
        assertEquals(Set.of("a", "c"), g.get("b"));
        assertEquals(Set.of("a", "b"), g.get("c"));
    }

    @Test
    void liveThroughLoopVariablesInterfere() {
        Map<String, Set<String>> g = RegAlloc.interference(Function.parse(Fixtures.LOOP));
        assertEquals(Set.of("c", "i", "n"), g.get("one"));   // c = lt i, n is defined while `one` is live around the loop
        assertTrue(g.get("c").containsAll(Set.of("i", "n", "one")));
        assertEquals(Set.of("c", "n", "one"), g.get("i"));   // i vs c: c = lt i, n defines c while i is live
    }

    @Test
    void colourWithThreeAndTwoRegisters() {
        Function f = Function.parse(STRAIGHT);
        RegAlloc.Allocation three = RegAlloc.allocate(f, 3);
        assertEquals(Set.of(), three.spilled());
        assertEquals(Map.of("a", 2, "b", 1, "x", 0, "y", 0, "z", 0), three.regs());
        // k = 2: simplify z(0), y(1); then a,b,x all have degree 2 -> potential spill a (ties: smaller name);
        // pop x->0, b->1, a: neighbours b(1), x(0) -> spilled; y->0 (b=1); z->0.
        RegAlloc.Allocation two = RegAlloc.allocate(f, 2);
        assertEquals(Set.of("a"), two.spilled());
        assertEquals(Map.of("x", 0, "b", 1, "y", 0, "z", 0), two.regs());
    }

    @Test
    void optimisticColouringColoursAFourCycleWithTwoRegisters() {
        // Every node has degree 2 = k, so nothing simplifies: a potential spill is pushed, yet the cycle is 2-colourable.
        RegAlloc.Allocation a = RegAlloc.color(graph("a-b", "b-c", "c-d", "d-a"), 2);
        assertEquals(Set.of(), a.spilled());
        assertValid(graph("a-b", "b-c", "c-d", "d-a"), a);
    }

    @Test
    void oddCycleAndCliqueMustSpill() {
        Map<String, Set<String>> c5 = graph("a-b", "b-c", "c-d", "d-e", "e-a");
        RegAlloc.Allocation a = RegAlloc.color(c5, 2);
        assertEquals(1, a.spilled().size());
        assertValid(c5, a);
        Map<String, Set<String>> k4 = graph("a-b", "a-c", "a-d", "b-c", "b-d", "c-d");
        RegAlloc.Allocation b = RegAlloc.color(k4, 3);
        assertEquals(Set.of("a"), b.spilled());           // potential spill is the smallest name among equal degrees
        assertEquals(Map.of("b", 2, "c", 1, "d", 0), b.regs());
        assertEquals(Set.of(), RegAlloc.color(k4, 4).spilled());
    }

    /**
     * Degrees a2 b2 c3 d3 with k = 2: nothing has degree below k, so the largest degree (tie: smaller name) c is pushed as
     * a potential spill; then a(1), b(1), d(0) simplify in that order. Pops: d->0, b->1, a->1, c has neighbours using 0 and 1.
     * A "degree <= k simplifies" variant would push a first and spill a and b instead.
     */
    @Test
    void potentialSpillIsTheHighestDegreeNode() {
        Map<String, Set<String>> g = graph("a-c", "a-d", "b-c", "b-d", "c-d");
        RegAlloc.Allocation a = RegAlloc.color(g, 2);
        assertEquals(Set.of("c"), a.spilled());
        assertEquals(Map.of("d", 0, "b", 1, "a", 1), a.regs());
    }

    /** A second, list-based implementation of the selection rules in TASK.md, compared exactly on random graphs. */
    private static RegAlloc.Allocation oracleColour(Map<String, Set<String>> g, int k) {
        java.util.List<String> names = new java.util.ArrayList<>(g.keySet());
        Map<String, Integer> deg = new TreeMap<>();
        for (String v : names) {
            deg.put(v, g.get(v).size());
        }
        java.util.List<String> stack = new java.util.ArrayList<>();
        while (!names.isEmpty()) {
            String best = null;
            for (String v : names) {                       // smallest degree below k, ties by smaller name
                if (deg.get(v) < k && (best == null || deg.get(v) < deg.get(best)
                        || deg.get(v).equals(deg.get(best)) && v.compareTo(best) < 0)) {
                    best = v;
                }
            }
            if (best == null) {
                for (String v : names) {                   // largest degree, ties by smaller name
                    if (best == null || deg.get(v) > deg.get(best)
                            || deg.get(v).equals(deg.get(best)) && v.compareTo(best) < 0) {
                        best = v;
                    }
                }
            }
            names.remove(best);
            stack.add(best);
            for (String n : g.get(best)) {
                if (names.contains(n)) {
                    deg.put(n, deg.get(n) - 1);
                }
            }
        }
        Map<String, Integer> regs = new TreeMap<>();
        Set<String> spilled = new TreeSet<>();
        java.util.Collections.reverse(stack);
        for (String v : stack) {
            boolean[] taken = new boolean[k];
            for (String n : g.get(v)) {
                if (regs.containsKey(n)) {
                    taken[regs.get(n)] = true;
                }
            }
            int r = 0;
            while (r < k && taken[r]) {
                r++;
            }
            if (r == k) {
                spilled.add(v);
            } else {
                regs.put(v, r);
            }
        }
        return new RegAlloc.Allocation(regs, spilled);
    }

    @Test
    void colouringMatchesTheSecondImplementationExactly() {
        Random rnd = new Random(909L);
        int differentFromPlainGreedyOrder = 0;
        for (int round = 0; round < 400; round++) {
            int n = 3 + rnd.nextInt(8);
            Map<String, Set<String>> g = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                g.put("n" + i, new TreeSet<>());
            }
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (rnd.nextInt(2) == 0) {
                        g.get("n" + i).add("n" + j);
                        g.get("n" + j).add("n" + i);
                    }
                }
            }
            int k = 2 + rnd.nextInt(3);
            RegAlloc.Allocation got = RegAlloc.color(g, k);
            RegAlloc.Allocation want = oracleColour(g, k);
            assertEquals(want, got, "round " + round + " k=" + k + " graph " + g);
            differentFromPlainGreedyOrder += got.spilled().isEmpty() ? 0 : 1;
        }
        assertTrue(differentFromPlainGreedyOrder > 100, "runs with spills: " + differentFromPlainGreedyOrder);
    }

    @Test
    void parametersInterfereWithVariablesReadBeforeAnyDefinition() {
        // x is defined on one path only, so it is live into the entry; parameter a must not share its register.
        Function f = Function.parse("func f(a)\nb:\n  br a, c, d\nc:\n  x = const 1\n  jmp d\nd:\n  ret x\n");
        assertEquals(Set.of("x"), RegAlloc.interference(f).get("a"));
        assertEquals(Set.of("a"), RegAlloc.interference(f).get("x"));
    }

    @Test
    void isolatedNodesAndBadArguments() {
        Map<String, Set<String>> g = new TreeMap<>();
        g.put("lonely", new TreeSet<>());
        assertEquals(Map.of("lonely", 0), RegAlloc.color(g, 1).regs());
        assertThrows(IllegalArgumentException.class, () -> RegAlloc.color(g, 0));
        assertThrows(IllegalArgumentException.class, () -> RegAlloc.allocate(Function.parse(STRAIGHT), -1));
    }

    @Test
    void renameRequiresACompleteAllocation() {
        Function f = Function.parse(STRAIGHT);
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> RegAlloc.rename(f, RegAlloc.allocate(f, 2)));
        assertTrue(e.getMessage().contains("spilled") && e.getMessage().contains("[a]"), e.getMessage());
        Function r = RegAlloc.rename(f, RegAlloc.allocate(f, 3));
        assertEquals("""
                func r(r2, r1)
                entry:
                  r0 = add r2, r1
                  r0 = mul r0, r2
                  r0 = add r0, r1
                  ret r0
                """, r.toText());
        assertEquals(Interp.run(f, new long[] {3, 4}, 100), Interp.run(r, new long[] {3, 4}, 100));
    }

    private static void assertValid(Map<String, Set<String>> g, RegAlloc.Allocation a) {
        for (var e : g.entrySet()) {
            assertTrue(a.regs().containsKey(e.getKey()) ^ a.spilled().contains(e.getKey()), "exactly one of coloured/spilled: " + e.getKey());
            for (String n : e.getValue()) {
                if (a.regs().containsKey(e.getKey()) && a.regs().containsKey(n)) {
                    assertNotEquals(a.regs().get(e.getKey()), a.regs().get(n), e.getKey() + "~" + n);
                }
            }
        }
    }

    @Test
    void randomGraphsColourValidly() {
        Random rnd = new Random(5150L);
        int spilledRuns = 0;
        int cleanRuns = 0;
        for (int round = 0; round < 300; round++) {
            int n = 2 + rnd.nextInt(12);
            Map<String, Set<String>> g = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                g.put("n" + i, new TreeSet<>());
            }
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (rnd.nextInt(3) == 0) {
                        g.get("n" + i).add("n" + j);
                        g.get("n" + j).add("n" + i);
                    }
                }
            }
            int k = 1 + rnd.nextInt(5);
            RegAlloc.Allocation a = RegAlloc.color(g, k);
            assertValid(g, a);
            for (int reg : a.regs().values()) {
                assertTrue(reg >= 0 && reg < k);
            }
            if (k >= n) {
                assertEquals(Set.of(), a.spilled(), "k >= n never spills");
            }
            spilledRuns += a.spilled().isEmpty() ? 0 : 1;
            cleanRuns += a.spilled().isEmpty() ? 1 : 0;
        }
        assertTrue(spilledRuns > 50 && cleanRuns > 50, "spilled " + spilledRuns + " clean " + cleanRuns);
    }

    @Test
    void renamedProgramsComputeTheSameResults() {
        Random rnd = new Random(8675309L);
        int renamed = 0;
        int tight = 0;
        for (int round = 0; round < 150; round++) {
            Function f = Function.parse(Gen.structured(rnd, 2, 6));
            int vars = Oracles.allVars(f).size();
            for (int k : new int[] {vars, 6, 4}) {
                RegAlloc.Allocation a = RegAlloc.allocate(f, k);
                if (!a.spilled().isEmpty()) {
                    assertTrue(k < vars);
                    continue;
                }
                Function g = RegAlloc.rename(f, a);
                renamed++;
                tight += k < vars ? 1 : 0;
                for (long[] args : Gen.argSets(rnd, 2, 5)) {
                    Optional<Long> want = Interp.run(f, args, 20_000);
                    assertEquals(want, Interp.run(g, args, 20_000), "round " + round + " k=" + k + "\n" + f.toText() + "\n--\n" + g.toText());
                }
            }
        }
        assertTrue(renamed > 150, "renamed programs: " + renamed);
        assertTrue(tight > 15, "renamed with fewer registers than variables: " + tight);
    }

    /** Negative control: collapsing every non-parameter variable into one register must be caught by the same equivalence check. */
    @Test
    void aWrongAllocationIsDetectedByTheInterpreter() {
        Random rnd = new Random(2024L);
        int caught = 0;
        for (int round = 0; round < 60; round++) {
            Function f = Function.parse(Gen.structured(rnd, 2, 5));
            Map<String, Integer> all = new TreeMap<>();
            for (String v : Oracles.allVars(f)) {
                int pi = f.params().indexOf(v);
                all.put(v, pi >= 0 ? pi : 5);   // distinct parameter registers (a Function rejects duplicates), all else shared
            }
            Function bad = RegAlloc.rename(f, new RegAlloc.Allocation(all, Set.of()));
            for (long[] args : Gen.argSets(rnd, 2, 5)) {
                Optional<Long> good = Interp.run(f, args, 20_000);
                Optional<Long> got;
                try {
                    got = Interp.run(bad, args, 20_000);
                } catch (IllegalStateException | IllegalArgumentException e) {
                    got = Optional.empty();
                }
                if (!good.equals(got)) {
                    caught++;
                    break;
                }
            }
        }
        assertTrue(caught > 50, "wrong allocations detected: " + caught + " of 60");
    }
}

package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Random;
import java.util.Set;
import org.junit.jupiter.api.Test;

class LivenessTest {
    @Test
    void countedLoop() {
        Cfg c = new Cfg(Function.parse(Fixtures.LOOP));
        Liveness lv = new Liveness(c);
        assertEquals(Set.of("n"), lv.liveIn(0));
        assertEquals(Set.of("i", "n", "one"), lv.liveOut(0));
        assertEquals(Set.of("i", "n", "one"), lv.liveIn(1));
        assertEquals(Set.of("i", "n", "one"), lv.liveOut(1));
        assertEquals(Set.of("i", "n", "one"), lv.liveIn(2));
        assertEquals(Set.of("i"), lv.liveIn(3));
        assertEquals(Set.of(), lv.liveOut(3));
        assertEquals(List.of(Set.of("i", "n"), Set.of("i", "n", "one"), Set.of("i", "n", "one")), lv.liveAfter(0));
        // head: c = lt i, n ; br c, ... -> after the lt only c and the loop-carried names are live.
        assertEquals(List.of(Set.of("c", "i", "n", "one"), Set.of("i", "n", "one")), lv.liveAfter(1));
        assertEquals(List.of(Set.of("i", "n", "one"), Set.of("i", "n", "one")), lv.liveAfter(2));
        assertEquals(List.of(Set.of()), lv.liveAfter(3));
    }

    @Test
    void diamondJoinKeepsOnlyWhatIsRead() {
        Cfg c = new Cfg(Function.parse(Fixtures.DIAMOND));
        Liveness lv = new Liveness(c);
        assertEquals(Set.of("a"), lv.liveIn(0));
        assertEquals(Set.of("x"), lv.liveOut(1));
        assertEquals(Set.of("x"), lv.liveIn(3));
        assertEquals(Set.of(), lv.liveIn(1));           // x is defined first thing in the arm
        assertEquals(Set.of("c"), lv.liveAfter(0).get(0));
    }

    @Test
    void redefinitionKillsLiveness() {
        Function f = Function.parse("func k(a)\nb:\n  x = const 1\n  x = const 2\n  ret x\n");
        Liveness lv = new Liveness(new Cfg(f));
        assertEquals(List.of(Set.of(), Set.of("x"), Set.of()), lv.liveAfter(0));
        assertEquals(Set.of(), lv.liveIn(0));
    }

    @Test
    void unreachableBlocksAreAnalysedToo() {
        Function f = Function.parse("func d(a)\nb:\n  ret a\nx:\n  y = add a, a\n  ret y\n");
        Liveness lv = new Liveness(new Cfg(f));
        assertEquals(Set.of("a"), lv.liveIn(1));
        assertEquals(Set.of("y"), lv.liveAfter(1).get(0));
    }

    @Test
    void randomProgramsMatchBruteForcePathSearch() {
        Random rnd = new Random(31337L);
        int checkedPoints = 0;
        int nonEmpty = 0;
        for (int round = 0; round < 250; round++) {
            String src = round % 2 == 0 ? Gen.randomCfg(rnd) : Gen.structured(rnd, 2, 4);
            Function f = Function.parse(src);
            Cfg c = new Cfg(f);
            Liveness lv = new Liveness(c);
            for (int b = 0; b < c.size(); b++) {
                assertEquals(Oracles.liveIn(f, c, b), lv.liveIn(b), "liveIn b" + b + " round " + round + "\n" + src);
                List<Set<String>> after = lv.liveAfter(b);
                assertEquals(f.blocks().get(b).instrs().size(), after.size());
                for (int i = 0; i < after.size(); i++) {
                    assertEquals(Oracles.liveAfter(f, c, b, i), after.get(i), "liveAfter b" + b + "." + i + " round " + round + "\n" + src);
                    checkedPoints++;
                    nonEmpty += after.get(i).isEmpty() ? 0 : 1;
                }
                // liveOut(b) is what is live after the terminator.
                assertEquals(after.get(after.size() - 1), lv.liveOut(b));
            }
        }
        assertTrue(checkedPoints > 3000, "points: " + checkedPoints);
        assertTrue(nonEmpty > checkedPoints / 2, "non-empty live sets: " + nonEmpty + " of " + checkedPoints);
    }
}

package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Random;
import java.util.Set;
import org.junit.jupiter.api.Test;

class LoopsTest {
    private static Loops loops(String src) {
        Cfg c = new Cfg(Function.parse(src));
        return new Loops(c, new Dominators(c));
    }

    private static final String NESTED = """
            func n(a)
            entry:
              jmp outer
            outer:
              br a, inner, done
            inner:
              br a, inner2, outerTail
            inner2:
              jmp inner
            outerTail:
              jmp outer
            done:
              ret a
            """;                      // entry0 outer1 inner2 inner2b3 outerTail4 done5

    @Test
    void countedLoop() {
        Loops l = loops(Fixtures.LOOP);
        assertEquals(List.of(new Loops.Loop(1, Set.of(1, 2), List.of(2))), l.loops());
        assertEquals(List.of(0, 1, 1, 0), List.of(l.depth(0), l.depth(1), l.depth(2), l.depth(3)));
        assertTrue(l.reducible());
    }

    @Test
    void nestedLoops() {
        Loops l = loops(NESTED);
        assertEquals(2, l.loops().size());
        assertEquals(new Loops.Loop(1, Set.of(1, 2, 3, 4), List.of(4)), l.loops().get(0));
        assertEquals(new Loops.Loop(2, Set.of(2, 3), List.of(3)), l.loops().get(1));
        assertEquals(List.of(0, 1, 2, 2, 1, 0), List.of(l.depth(0), l.depth(1), l.depth(2), l.depth(3), l.depth(4), l.depth(5)));
        assertTrue(l.reducible());
    }

    @Test
    void twoBackEdgesToOneHeaderFormOneLoop() {
        Loops l = loops("""
                func m(a)
                h:
                  br a, p, q
                p:
                  br a, h, x
                q:
                  jmp h
                x:
                  ret a
                """);                 // h0 p1 q2 x3
        assertEquals(List.of(new Loops.Loop(0, Set.of(0, 1, 2), List.of(1, 2))), l.loops());
        assertEquals(1, l.depth(2));
        assertEquals(0, l.depth(3));
    }

    @Test
    void selfLoopAndIrreducibleCycle() {
        assertEquals(List.of(new Loops.Loop(0, Set.of(0), List.of(0))), loops(Fixtures.SELF_LOOP).loops());
        Loops irr = loops(Fixtures.IRREDUCIBLE);
        assertEquals(List.of(), irr.loops());
        assertFalse(irr.reducible());
        assertEquals(0, irr.depth(1));
    }

    @Test
    void deadCodeLoopIsIgnored() {
        Loops l = loops("func d(a)\nb:\n  ret a\nx:\n  jmp y\ny:\n  jmp x\n");
        assertEquals(List.of(), l.loops());
        assertTrue(l.reducible());
        assertEquals(0, l.depth(1));
    }

    @Test
    void randomGraphsMatchOracles() {
        Random rnd = new Random(99L);
        int withLoops = 0;
        int irreducible = 0;
        for (int round = 0; round < 500; round++) {
            Cfg c = new Cfg(Function.parse(Gen.randomCfg(rnd)));
            Dominators d = new Dominators(c);
            Loops l = new Loops(c, d);
            assertEquals(Oracles.reducible(c), l.reducible(), "round " + round);
            int[] depth = new int[c.size()];
            for (Loops.Loop loop : l.loops()) {
                assertEquals(Oracles.loopBody(c, loop.header(), loop.tails()), loop.blocks(), "loop " + loop + " round " + round);
                for (int t : loop.tails()) {
                    assertTrue(c.succ(t).contains(loop.header()) && d.dominates(loop.header(), t));
                }
                for (int b : loop.blocks()) {
                    depth[b]++;
                }
            }
            for (int b = 0; b < c.size(); b++) {
                assertEquals(depth[b], l.depth(b));
            }
            // Every back edge of the graph is accounted for by some loop tail.
            for (int t = 0; t < c.size(); t++) {
                for (int h : c.succ(t)) {
                    if (d.dominates(h, t)) {
                        final int tail = t;
                        final int header = h;
                        assertTrue(l.loops().stream().anyMatch(x -> x.header() == header && x.tails().contains(tail)));
                    }
                }
            }
            withLoops += l.loops().isEmpty() ? 0 : 1;
            irreducible += l.reducible() ? 0 : 1;
        }
        assertTrue(withLoops > 100, "graphs with loops: " + withLoops);
        assertTrue(irreducible > 10, "irreducible graphs: " + irreducible);
    }
}

package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Optional;
import java.util.Random;
import org.junit.jupiter.api.Test;

class DceTest {
    @Test
    void removesDeadChainsAndUnreachableBlocks() {
        Function f = Function.parse("""
                func d(a, b)
                entry:
                  t = add a, b
                  dead1 = mul t, t
                  dead2 = add dead1, a
                  u = const 5
                  jmp next
                next:
                  ret t
                orphan:
                  ret a
                """);
        assertEquals("""
                func d(a, b)
                entry:
                  t = add a, b
                  jmp next
                next:
                  ret t
                """, Dce.run(f).toText());
    }

    @Test
    void overwrittenDefinitionIsDeadButTheLastOneStays() {
        Function f = Function.parse("func o(a)\nb:\n  x = const 1\n  x = const 2\n  ret x\n");
        assertEquals("func o(a)\nb:\n  x = const 2\n  ret x\n", Dce.run(f).toText());
    }

    @Test
    void definitionsLiveOnOnlyOneBranchSurvive() {
        Function f = Function.parse(Fixtures.DIAMOND);
        assertEquals(f, Dce.run(f));
    }

    @Test
    void loopCarriedSelfUseIsNotRemoved() {
        // Documented limitation: k is read only by its own update, but liveness cannot tell.
        Function f = Function.parse("""
                func l(n)
                entry:
                  k = const 0
                  i = const 0
                  one = const 1
                  jmp head
                head:
                  c = lt i, n
                  br c, body, exit
                body:
                  k = add k, one
                  i = add i, one
                  jmp head
                exit:
                  ret i
                """);
        assertEquals(f, Dce.run(f));
    }

    @Test
    void deadParametersAndTerminatorsStay() {
        Function f = Function.parse("func p(a, b)\nb0:\n  br a, b0, b1\nb1:\n  ret a\n");
        assertEquals(f, Dce.run(f));
    }

    @Test
    void idempotentAndSemanticsPreservingOnRandomPrograms() {
        Random rnd = new Random(424242L);
        int shrunk = 0;
        int comparisons = 0;
        for (int round = 0; round < 200; round++) {
            Function f = Function.parse(Gen.structured(rnd, 2, 5));
            Function g = Dce.run(f);
            assertEquals(g, Dce.run(g), "idempotent, round " + round);
            assertEquals(g, Function.parse(g.toText()));
            int before = count(f);
            int after = count(g);
            assertTrue(after <= before);
            shrunk += after < before ? 1 : 0;
            for (long[] args : Gen.argSets(rnd, 2, 6)) {
                Optional<Long> want = Interp.run(f, args, 20_000);
                assertTrue(want.isPresent(), "generator programs terminate; round " + round);
                assertEquals(want, Interp.run(g, args, 20_000), "round " + round + "\n" + f.toText() + "\n--\n" + g.toText());
                comparisons++;
            }
            // Nothing non-terminator that remains is dead right after it.
            Liveness lv = new Liveness(new Cfg(g));
            for (int b = 0; b < g.blocks().size(); b++) {
                List<Instr> ins = g.blocks().get(b).instrs();
                for (int i = 0; i < ins.size(); i++) {
                    final int bi = b;
                    final int ii = i;
                    ins.get(i).def().ifPresent(d -> assertTrue(lv.liveAfter(bi).get(ii).contains(d), "dead def left: " + ins.get(ii)));
                }
            }
        }
        assertTrue(shrunk > 100, "programs that shrank: " + shrunk);
        assertEquals(1200, comparisons);
    }

    private static int count(Function f) {
        return f.blocks().stream().mapToInt(b -> b.instrs().size()).sum();
    }
}

package ae.cfg;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/** Slow, definition-level oracles written independently of the production algorithms. */
final class Oracles {
    private Oracles() { }

    /** Blocks reachable from the entry without ever entering {@code removed} (-1: remove nothing). */
    static Set<Integer> reachAvoiding(Cfg cfg, int removed) {
        Set<Integer> seen = new HashSet<>();
        if (removed == 0) {
            return seen;
        }
        ArrayDeque<Integer> work = new ArrayDeque<>(List.of(0));
        seen.add(0);
        while (!work.isEmpty()) {
            for (int s : cfg.succ(work.pop())) {
                if (s != removed && seen.add(s)) {
                    work.push(s);
                }
            }
        }
        return seen;
    }

    /** a dominates b iff b is reachable and every path entry -> b passes through a. */
    static boolean dominates(Cfg cfg, int a, int b) {
        Set<Integer> all = reachAvoiding(cfg, -1);
        if (!all.contains(b) || !all.contains(a)) {
            return false;
        }
        return a == b || !reachAvoiding(cfg, a).contains(b);
    }

    /** The strict dominator of b that every other strict dominator of b dominates (-1 if none). */
    static int idom(Cfg cfg, int b) {
        List<Integer> strict = new ArrayList<>();
        for (int d = 0; d < cfg.size(); d++) {
            if (d != b && dominates(cfg, d, b)) {
                strict.add(d);
            }
        }
        for (int cand : strict) {
            boolean closest = true;
            for (int other : strict) {
                if (!dominates(cfg, other, cand)) {
                    closest = false;
                }
            }
            if (closest) {
                return cand;
            }
        }
        return -1;
    }

    /** DF(a) = { y : a dominates some predecessor of y, and a does not strictly dominate y }. Needs no entry special case: the definition already counts a back edge into the entry. */
    static Set<Integer> frontier(Cfg cfg, int a) {
        Set<Integer> out = new TreeSet<>();
        for (int y = 0; y < cfg.size(); y++) {
            boolean domPred = false;
            for (int p : cfg.pred(y)) {
                domPred |= dominates(cfg, a, p);
            }
            boolean strict = a != y && dominates(cfg, a, y);
            if (domPred && !strict && dominates(cfg, 0, y)) {
                out.add(y);
            }
        }
        return out;
    }

    /** Natural loop body of header h: h plus every block that can reach a tail without entering h. */
    static Set<Integer> loopBody(Cfg cfg, int h, List<Integer> tails) {
        Set<Integer> body = new TreeSet<>(List.of(h));
        for (int n = 0; n < cfg.size(); n++) {
            if (n == h || !cfg.reachable(n)) {
                continue;
            }
            ArrayDeque<Integer> work = new ArrayDeque<>(List.of(n));
            Set<Integer> seen = new HashSet<>(List.of(n));
            boolean hit = false;
            while (!work.isEmpty() && !hit) {
                int x = work.pop();
                hit = tails.contains(x);
                for (int s : cfg.succ(x)) {
                    if (s != h && seen.add(s)) {
                        work.push(s);
                    }
                }
            }
            if (hit) {
                body.add(n);
            }
        }
        return body;
    }

    /** T1/T2 reduction on the reachable subgraph: reducible iff it collapses to a single node. */
    static boolean reducible(Cfg cfg) {
        int n = cfg.size();
        List<Set<Integer>> succ = new ArrayList<>();
        for (int b = 0; b < n; b++) {
            succ.add(new TreeSet<>());
            if (cfg.reachable(b)) {
                for (int s : cfg.succ(b)) {
                    succ.get(b).add(s);
                }
            }
        }
        Set<Integer> alive = new TreeSet<>();
        for (int b = 0; b < n; b++) {
            if (cfg.reachable(b)) {
                alive.add(b);
            }
        }
        boolean changed = true;
        while (changed && alive.size() > 1) {
            changed = false;
            for (int b : alive) {
                if (succ.get(b).remove(b)) {      // T1: delete a self loop
                    changed = true;
                }
            }
            for (int b : new ArrayList<>(alive)) {
                if (b == 0) {
                    continue;
                }
                List<Integer> preds = new ArrayList<>();
                for (int p : alive) {
                    if (succ.get(p).contains(b)) {
                        preds.add(p);
                    }
                }
                if (preds.size() == 1) {          // T2: merge b into its unique predecessor
                    int p = preds.get(0);
                    succ.get(p).remove(b);
                    succ.get(p).addAll(succ.get(b));
                    alive.remove(b);
                    changed = true;
                }
            }
        }
        return alive.size() == 1;
    }

    /** Is variable v read before being redefined, scanning forward from instruction {@code from} of block b? */
    static boolean readsBeforeDef(Function f, Cfg cfg, String v, int b, int from, Set<Integer> visitedBlocks) {
        List<Instr> ins = f.blocks().get(b).instrs();
        for (int j = from; j < ins.size(); j++) {
            if (ins.get(j).uses().contains(v)) {
                return true;
            }
            if (ins.get(j).def().map(v::equals).orElse(false)) {
                return false;
            }
        }
        for (int s : cfg.succ(b)) {
            if (visitedBlocks.add(s) && readsBeforeDef(f, cfg, v, s, 0, visitedBlocks)) {
                return true;
            }
        }
        return false;
    }

    static Set<String> allVars(Function f) {
        Set<String> vars = new TreeSet<>(f.params());
        for (Block b : f.blocks()) {
            for (Instr i : b.instrs()) {
                i.def().ifPresent(vars::add);
                vars.addAll(i.uses());
            }
        }
        return vars;
    }

    static Set<String> liveIn(Function f, Cfg cfg, int b) {
        Set<String> out = new TreeSet<>();
        for (String v : allVars(f)) {
            if (readsBeforeDef(f, cfg, v, b, 0, new HashSet<>())) {
                out.add(v);
            }
        }
        return out;
    }

    static Set<String> liveAfter(Function f, Cfg cfg, int b, int idx) {
        Set<String> out = new TreeSet<>();
        for (String v : allVars(f)) {
            if (readsBeforeDef(f, cfg, v, b, idx + 1, new HashSet<>())) {
                out.add(v);
            }
        }
        return out;
    }
}

package ae.cfg;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Random;
import java.util.Set;
import org.junit.jupiter.api.Test;

class DominatorsTest {
    private static Cfg cfg(String src) {
        return new Cfg(Function.parse(src));
    }

    private static int[] idoms(Dominators d, int n) {
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            out[i] = d.idom(i);
        }
        return out;
    }

    @Test
    void cfgEdgesAndOrder() {
        Cfg c = cfg(Fixtures.DIAMOND);
        assertEquals(4, c.size());
        assertEquals(List.of(1, 2), c.succ(0));
        assertEquals(List.of(3), c.succ(1));
        assertEquals(List.of(), c.succ(3));
        assertEquals(List.of(1, 2), c.pred(3));
        assertEquals(List.of(0, 1, 2, 3), c.rpo().stream().sorted().toList());
        assertEquals(0, c.rpo().get(0));
        assertEquals(3, c.rpo().get(3));           // join after both arms
        assertEquals(2, c.index("right"));
        assertThrows(IllegalArgumentException.class, () -> c.index("nope"));
    }

    @Test
    void duplicateBranchTargetsGiveOneEdge() {
        Cfg c = cfg("func f(a)\nb:\n  br a, c, c\nc:\n  ret a\n");
        assertEquals(List.of(1), c.succ(0));
        assertEquals(List.of(0), c.pred(1));
    }

    @Test
    void rpoOmitsUnreachableBlocks() {
        Cfg c = cfg(Fixtures.UNREACHABLE);
        assertEquals(5, c.size());
        assertFalse(c.reachable(4));
        assertEquals(4, c.rpo().size());
        assertFalse(c.rpo().contains(4));
        assertEquals(List.of(1, 2, 4), c.pred(3));   // preds still list the dead block
    }

    @Test
    void diamond() {
        Cfg c = cfg(Fixtures.DIAMOND);
        Dominators d = new Dominators(c);
        assertArrayEquals(new int[] {-1, 0, 0, 0}, idoms(d, 4));
        assertEquals(Set.of(), d.frontier(0));
        assertEquals(Set.of(3), d.frontier(1));
        assertEquals(Set.of(3), d.frontier(2));
        assertEquals(Set.of(), d.frontier(3));
        assertEquals(List.of(1, 2, 3), d.children(0));
        assertTrue(d.dominates(0, 3));
        assertTrue(d.dominates(3, 3));
        assertFalse(d.dominates(1, 3));
        assertFalse(d.dominates(3, 0));
    }

    @Test
    void countedLoop() {
        Dominators d = new Dominators(cfg(Fixtures.LOOP));
        assertArrayEquals(new int[] {-1, 0, 1, 1}, idoms(d, 4));
        assertEquals(Set.of(1), d.frontier(1));      // the header is in its own frontier
        assertEquals(Set.of(1), d.frontier(2));
        assertEquals(Set.of(), d.frontier(0));
        assertEquals(Set.of(), d.frontier(3));
        assertEquals(List.of(2, 3), d.children(1));
    }

    @Test
    void irreducibleCycleHasNoDominatingEntry() {
        Dominators d = new Dominators(cfg(Fixtures.IRREDUCIBLE));
        assertArrayEquals(new int[] {-1, 0, 0, 2}, idoms(d, 4));
        assertEquals(Set.of(2), d.frontier(1));
        assertEquals(Set.of(1), d.frontier(2));
        assertFalse(d.dominates(1, 2));
        assertFalse(d.dominates(2, 1));
        assertTrue(d.dominates(2, 3));
    }

    @Test
    void unreachableBlocksAreOutsideTheTree() {
        Dominators d = new Dominators(cfg(Fixtures.UNREACHABLE));
        assertArrayEquals(new int[] {-1, 0, 0, 0, -1}, idoms(d, 5));
        assertFalse(d.dominates(4, 3));
        assertFalse(d.dominates(0, 4));
        assertFalse(d.dominates(4, 4));
        assertEquals(Set.of(), d.frontier(4));
        assertEquals(Set.of(3), d.frontier(1));      // the dead predecessor adds nothing
        assertEquals(List.of(1, 2, 3), d.children(0));
    }

    @Test
    void entrySelfLoopPutsEntryInItsOwnFrontier() {
        Dominators d = new Dominators(cfg(Fixtures.SELF_LOOP));
        assertArrayEquals(new int[] {-1, 0}, idoms(d, 2));
        assertEquals(Set.of(0), d.frontier(0));
        assertEquals(Set.of(), d.frontier(1));
    }

    /** Linear chain of 40 blocks: recursion-free algorithms must cope, and idom is the previous block. */
    @Test
    void longChain() {
        StringBuilder sb = new StringBuilder("func c(a)\n");
        for (int i = 0; i < 40; i++) {
            sb.append("b").append(i).append(":\n  ").append(i == 39 ? "ret a" : "jmp b" + (i + 1)).append('\n');
        }
        Dominators d = new Dominators(cfg(sb.toString()));
        for (int i = 1; i < 40; i++) {
            assertEquals(i - 1, d.idom(i));
            assertEquals(Set.of(), d.frontier(i));
        }
    }

    @Test
    void randomGraphsMatchDefinitionOracles() {
        Random rnd = new Random(20261126L);
        int unreachable = 0;
        int cyclic = 0;
        int multi = 0;
        for (int round = 0; round < 400; round++) {
            Cfg c = cfg(Gen.randomCfg(rnd));
            Dominators d = new Dominators(c);
            boolean hasDead = false;
            for (int b = 0; b < c.size(); b++) {
                hasDead |= !c.reachable(b);
                assertEquals(Oracles.idom(c, b), d.idom(b), "idom of b" + b + " in round " + round);
                assertEquals(Oracles.frontier(c, b), d.frontier(b), "frontier of b" + b + " in round " + round);
                for (int a = 0; a < c.size(); a++) {
                    assertEquals(Oracles.dominates(c, a, b), d.dominates(a, b), a + " dom " + b + " round " + round);
                }
            }
            unreachable += hasDead ? 1 : 0;
            cyclic += c.pred(0).isEmpty() ? 0 : 1;
            multi += c.size() >= 5 ? 1 : 0;
        }
        assertTrue(unreachable > 40, "graphs with dead blocks: " + unreachable);
        assertTrue(cyclic > 10, "graphs with a back edge into the entry: " + cyclic);
        assertTrue(multi > 100, "graphs with >= 5 blocks: " + multi);
    }

    @Test
    void childrenPartitionTheReachableBlocks() {
        Random rnd = new Random(7);
        for (int round = 0; round < 200; round++) {
            Cfg c = cfg(Gen.randomCfg(rnd));
            Dominators d = new Dominators(c);
            int edges = 0;
            for (int b = 0; b < c.size(); b++) {
                for (int ch : d.children(b)) {
                    assertEquals(b, d.idom(ch));
                    edges++;
                }
            }
            int reachable = (int) java.util.stream.IntStream.range(0, c.size()).filter(c::reachable).count();
            assertEquals(reachable - 1, edges);
        }
    }
}
